    def collatz_sequence(n):
        sequence = [n]
        while len(sequence) > 0:
            last_term = sequence[-1]
            if last_term % 2 == 0:
                next_term = last_term // 2
            else:
                next_term = (last_term * 3) + 1
            sequence.append(next_term)
        return sequence

    def odd_numbers_in_collatz(n):
        collatz_seq = collatz_sequence(n)
        return [term for term in collatz_seq if term % 2 != 0]

